// Overloaded function set
void process(int value);    // Overload for integers
void process(bool flag);    // Overload for booleans
void process(void* ptr);    // Overload for pointers

// C++98-style calls
process(0);      // ALWAYS calls process(int)
process(NULL);   // Typically calls process(int), but might be ambiguous.
                 // It will NEVER call process(void*).
